mapper.select:
	select p.post_no, title, p.member_uuid, name, post_like, reg_date, star
	from post p
	join member m on p.member_uuid = m.member_uuid
	join (select post_no, avg(star) star from star group by post_no) s on p.post_no = s.post_no

		join post_brand pb on p.post_no = pb.post_no



		join post_taste pt on p.post_no = pt.post_no



		join post_ingredient pi on p.post_no = pi.post_no


		p.state=1




        			#{brand_id}







        			#{taste_id}







        			#{ingredient_id}






				title like concat('%',#{keyword},'%') or content like concat('%',#{keyword},'%')





				cost >= #{min_cost}





					cost <= #{max_cost}




	group by p.post_no


			count(distinct brand_id)=#{brandsize}



				count(distinct taste_id)=#{tastesize}




				count(distinct ingredient_id)=#{ingredientsize}




		order by post_no


		order by post_like desc


		order by star desc

	limit #{skip}, #{size}

